import React, { Fragment } from "react";
import Image from '../../assests/pic2.jpg';
import classes from './HomePage.module.css';
import UserForm from "./UserForm";
 const HomePage=(props)=>{

    return(
        <Fragment>
            <header className={classes.header}>
                <h1> 🔱 Welcome to Shiv Resturant🔱  </h1>
                <h5>Free Home Delivery Avilable upto 10km  </h5>
               
            </header>
            <div className={classes.img}>
               <img src={Image} style={{ width: '400px', height: '300px' }}alt="gana "></img>

            </div>
            <div className={classes.btn}>

               <button onclick>New user Click to register address</button>
                
                <button onClick={props.onClick}>CLICK To ORDER</button>
               
            </div>
            <footer className={classes.footer}>
                 <h4>Address:</h4>
                 <p>Modinagar National highway </p>
            </footer>
        </Fragment>
    )
 }
 export default HomePage;
